insert into appeals (id, claim_id, analysis, letter, p2p, model, latency_ms, created_at, is_cached, is_active) values ('APL-CACHE-004', 'CLM-004', '{"verdict":"appeal","confidence":0.91,"denial_reason":"LVEF criteria not met for primary-prevention ICD. Claim denied under CARD-33.","policy_clause":{"policy_code":"CARD-33","quote":"An LVEF of 28% measured 52 days post-MI in a patient on 4 months of GDMT with NYHA class II symptoms meets all CARD-33 primary-prevention criteria."},"evidence":[{"quote":"MI date documented as 2026-02-08.","note_id":"N-401","timestamp":"2026-02-10T12:00:00Z"},{"quote":"Date of study: 2026-04-01 (52 days after MI dated 2026-02-08).","note_id":"N-402","timestamp":"2026-04-01T14:30:00Z"},{"quote":"LVEF estimated at 28% by biplane Simpson method.","note_id":"N-402","timestamp":"2026-04-01T14:30:00Z"},{"quote":"Patient has been on continuous guideline-directed medical therapy (carvedilol, ACE inhibitor, MRA, SGLT2i added 2026-03) for 4 months since MI. Remains NYHA class II","note_id":"N-403","timestamp":"2026-06-12T10:15:00Z"}],"gaps":[],"letter":{"sections":[{"heading":"Re: Appeal of Denial — CPT 33249 / Claim CLM-004","body":"We appeal the CO-50 denial alleging LVEF criteria were not met. The record shows LVEF 28% at 52 days post-MI, 4 months of GDMT, and NYHA II — meeting CARD-33 as documented."},{"heading":"Criteria mapping","body":"LVEF 28% on echo. Timing: echo at 52 days post-MI. GDMT: 4 months documented. Functional class: NYHA II."},{"heading":"Request","body":"Overturn the denial and pay CPT 33249. DRAFT — physician/billing review required."}],"citations":["CARD-33"]},"p2p":{"opening":"CARD-33 primary-prevention ICD — payer alleged LVEF criteria unmet, but echo shows 28% at 52 days with 4 months GDMT and NYHA II.","talking_points":["LVEF 28% on biplane Simpson echo.","Echo timed at 52 days post-MI.","4 months continuous GDMT; NYHA class II."],"likely_pushback":[{"objection":"Need a lower LVEF threshold for primary prevention.","respo