insert into appeals (id, claim_id, analysis, letter, p2p, model, latency_ms, created_at, is_cached, is_active) values ('APL-CACHE-005', 'CLM-005', '{"verdict":"uphold_denial","confidence":0.88,"denial_reason":"Lumbar MRI ordered without 6 weeks of conservative care and without red-flag indications per SPINE-04.","policy_clause":{"policy_code":"SPINE-04","quote":"Nine days of low back pain with a normal neurologic examination and no documented red flags does not meet medical necessity criteria."},"evidence":[{"quote":"Patient E-9914 reports 9 days of low back pain after lifting boxes at home.","note_id":"N-501","timestamp":"2026-09-01T13:20:00Z"},{"quote":"No red flags identified.","note_id":"N-501","timestamp":"2026-09-01T13:20:00Z"},{"quote":"Neurologic examination: strength 5/5 in all lower extremity myotomes, reflexes symmetric, sensation intact, negative straight-leg raise bilaterally.","note_id":"N-501","timestamp":"2026-09-01T13:20:00Z"}],"gaps":["Documentation gap — query the attending before write-off or external appeal.","No 6-week conservative care course documented before MRI order.","No red-flag features (progressive deficit, saddle anesthesia, bowel/bladder dysfunction, malignancy, infection, fracture) documented."],"letter":{"sections":[{"heading":"Internal assessment — documentation gap / query attending","body":"Current chart under SPINE-04 shows 9 days of nonspecific low back pain, normal neuro exam, and no red flags. MRI at day 9 does not meet documented medical necessity. Query the attending for omitted red-flag or conservative-care documentation before any write-off. Do not treat this as an automatic abandon."}],"citations":["SPINE-04"]},"p2p":{"opening":"Internal huddle only — documentation appears insufficient to overturn. Query the attending before write-off or external peer-to-peer.","talking_points":["Symptom duration 9 days — far below 6-week requirement.","Normal neurologic exam; no red flags documented.","SPINE-04 non-coverage language matches this presentation.","Ask attending whether red flags or prior conservative care exist outside this note."],"likely_pushback":[{"objection":"Billing wants to write this off now.","response":"Pause. Query the attending for omitted documentation first; only then decide appeal vs acceptance."}],"ask":"Query the attending for missing documentation before peer-to-peer or write-off."}}'::jsonb, '{"sections":[{"heading":"Internal assessment — documentation gap / query attending","body":"Current chart under SPINE-04 shows 9 days of nonspecific low back pain, normal neuro exam, and no red flags. MRI at day 9 does not meet documented medical necessity. Query the attending for omitted red-flag or conservative-care documentation before any write-off. Do not treat this as an automatic abandon."}],"citations":["SPINE-04"]}'::jsonb, '{"opening":"Internal huddle only — documentation appears insufficient to overturn. Query the attending before write-off or external peer-to-peer.","talking_points":["Symptom duration 9 days — far below 6-week requirement.","Normal neurologic exam; no red flags documented.","SPINE-04 non-coverage language matches this presentation.","Ask attending whether red flags or prior conservative care exist outside this note."],"likely_pushback":[{"objection":"Billing wants to write this off now.","response":"Pause. Query the attending for omitted documentation first; only then decide appeal vs acceptance."}],"ask":"Query the attending for missing documentation before peer-to-peer or write-off."}'::jsonb, 'gemma3', 3980, '2026-09-01T12:20:00Z', TRUE, FALSE);
